_NIQ = re.compile('[֑-ׇ]')
COMPILED = []
for w in W:
    key, cat, he, ar, dhe, dar, pat, nhe, nar = w
    COMPILED.append((key, re.compile(PRE + '(?:' + pat + ')')))


def find(*texts):
    """Ordered unique list of work keys mentioned in the given Hebrew texts."""
    found = []
    for t in texts:
        if not t:
            continue
        t = _NIQ.sub('', str(t).replace('\u05be', '-'))
        taken = []
        hits = []
        for key, rx in COMPILED:
            for m in rx.finditer(t):
                a, b = m.span()
                if any(a < y and x < b for x, y in taken):
                    continue
                taken.append((a, b))
                hits.append((a, key))
        for _, k in sorted(hits):
            if k not in found:
                found.append(k)
    return [k for k in found if k != 'sefer_haaggada']


TABLE_HEADERS = ['מפתח', 'קטגוריה', 'החיבור', 'المؤلَّف', 'זמן החיבור המשוער', 'زمن التأليف التقريبي', 'הערה', 'ملاحظة']


def table_rows():
    return [[k, c, he, ar, dhe, dar, nhe or None, nar or None] for (k, c, he, ar, dhe, dar, p, nhe, nar) in W if c != 'skip']


def load(rows):
    """dict key -> [he, ar, date_he, date_ar, note_he, note_ar, category]; values in the C sheet (if given) win."""
    d = {r[0]: [r[2], r[3], r[4], r[5], r[6] or None, r[7] or None, r[1]] for r in table_rows()}
    for r in rows or []:
        if r and r[0] in d:
            r = list(r) + [None] * 8
            d[r[0]] = [r[2] or d[r[0]][0], r[3] or d[r[0]][1], r[4] or d[r[0]][2], r[5] or d[r[0]][3],
                       r[6], r[7], r[1] or d[r[0]][6]]
    return d
